229	  const repositoryOriginal = material.includes("docs/guide/universal-ai-skill-inquiry-framework.md");
230	  if (!packageReference && !repositoryOriginal) return null;
231	  const normalizedName = String(name ?? "").toLowerCase();
232	  const command = String(input?.command ?? input?.cmd ?? "").toLowerCase();
233	  let rangeKind = "unknown";
234	  if (normalizedName.includes("grep") || /\brg\b|select-string|grep\b/u.test(command)) rangeKind = "search";
235	  else if (input?.offset !== undefined || input?.limit !== undefined || /\[[0-9]+\.\.[0-9]+\]|-totalcount|-tail|-skip|-first|sed\s+-n|head\b|tail\b/u.test(command)) rangeKind = "lines";
236	  else if (/byte|startbyte|endbyte/u.test(command)) rangeKind = "bytes";
237	  else if (normalizedName === "read" || /get-content|\bcat\b|\btype\b/u.test(command)) rangeKind = "whole";
238	  return { source: packageReference ? "package-reference" : "repository-original", primitive: String(name ?? "unknown"), rangeKind, returnedBytes };
