245	export function transcriptMetrics(host, bytes) {
246	  const pendingClaudeTools = new Map();
247	  const seenTools = new Set();
248	  const byKind = emptyKinds();
249	  const frameworkReads = [];
250	  let usageRaw = null;
251	  let claudeTotalCostUsd = null;
252	  let toolResultBytes = 0;
253	  let indexReturnedBytes = 0;
254	
255	  const recordTool = (id, name, input) => {
256	    const key = id ?? `${name}:${seenTools.size}`;
257	    if (seenTools.has(key)) return false;
258	    seenTools.add(key);
259	    byKind[toolKind(name, input)] += 1;
260	    return true;
261	  };
262	
263	  for (const line of bytes.toString("utf8").split(/\r?\n/u)) {
264	    if (!line) continue;
265	    let event;
266	    try { event = JSON.parse(line); } catch { continue; }
267	
268	    if (host === "codex" && event.type === "item.completed" && ["command_execution", "file_change", "mcp_tool_call"].includes(event.item?.type)) {
269	      const name = event.item.type;
270	      const input = { command: event.item.command ?? "" };
271	      if (recordTool(event.item.id, name, input)) {
272	        const returnedBytes = resultTextBytes(event.item.aggregated_output);
273	        toolResultBytes += returnedBytes;
274	        const observation = readObservation(name, input, returnedBytes);
275	        if (observation) frameworkReads.push(observation);
276	        if (`${event.item.command ?? ""}`.replaceAll("\\", "/").toLowerCase().includes("universalframeworkoriginal.index.json")) indexReturnedBytes += returnedBytes;
277	      }
278	    }
279	    if (host === "codex" && event.type === "turn.completed") usageRaw = event.usage ?? null;
280	
281	    if (host === "claude" && event.type === "assistant") {
282	      for (const item of event.message?.content ?? []) {
283	        if (item.type !== "tool_use" || !recordTool(item.id, item.name, item.input)) continue;
284	        pendingClaudeTools.set(item.id, { name: item.name, input: item.input ?? {} });
285	      }
286	    }
287	    if (host === "claude" && event.type === "user") {
288	      for (const item of event.message?.content ?? []) {
289	        if (item.type !== "tool_result") continue;
290	        const returnedBytes = resultTextBytes(item.content);
291	        toolResultBytes += returnedBytes;
292	        const tool = pendingClaudeTools.get(item.tool_use_id);
293	        if (!tool) continue;
294	        const observation = readObservation(tool.name, tool.input, returnedBytes);
295	        if (observation) frameworkReads.push(observation);
296	        const material = `${tool.name}\n${JSON.stringify(tool.input)}`.replaceAll("\\", "/").toLowerCase();
297	        if (material.includes("universalframeworkoriginal.index.json")) indexReturnedBytes += returnedBytes;
298	      }
299	    }
300	    if (host === "claude" && event.type === "result") {
301	      usageRaw = event.usage ?? null;
302	      claudeTotalCostUsd = event.total_cost_usd ?? null;
303	    }
304	  }
305	
306	  const claude = host === "claude" && usageRaw ? {
307	    uncachedInput: usageRaw.input_tokens ?? 0,
308	    cacheCreate: usageRaw.cache_creation_input_tokens ?? 0,
309	    cacheRead: usageRaw.cache_read_input_tokens ?? 0,
310	    output: usageRaw.output_tokens ?? 0,
311	    thinking: usageRaw.output_tokens_details?.thinking_tokens ?? 0,
312	  } : null;
313	  const codex = host === "codex" && usageRaw ? {
314	    inputTotal: usageRaw.input_tokens ?? 0,
315	    cachedInput: usageRaw.cached_input_tokens ?? 0,
316	    output: usageRaw.output_tokens ?? 0,
317	    reasoning: usageRaw.reasoning_output_tokens ?? 0,
318	  } : null;
319	  return {
320	    usageRaw,
321	    claudeTotalCostUsd,
322	    tokens: {
323	      claude,
324	      codex,
325	      billedInputTokens: claude ? claude.uncachedInput + claude.cacheCreate + claude.cacheRead : codex?.inputTotal ?? null,
326	      comparabilityScope: "same-host-only",
327	    },
328	    tools: { count: seenTools.size, byKind, comparabilityScope: "same-host-only" },
329	    toolResultBytes,
330	    frameworkReads,
331	    indexReturnedBytes,
332	  };
333	}
