394	  const frameworkBytesReadApprox = measured.frameworkReads.reduce((sum, read) => sum + read.returnedBytes, 0);
395	  const installedEntry = await readFile(resolve(installed, "SKILL.md"), "utf8");
396	  const validity = !preconditionsPass
397	    ? { status: "aborted-precondition", reason: preconditions.rows.filter((row) => !row.ok).map((row) => row.name).join(",") }
398	    : hostResult.code !== 0 && measured.tools.count === 0
399	      ? { status: "harness-defect", reason: `Host exited ${hostResult.code} before any observable tool call.` }
400	      : { status: "valid", reason: null };
401	  const receipt = {
