477	  const [action, ...args] = process.argv.slice(2);
478	  const options = parseArguments(args);
479	  const protocol = await json(protocolPath);
480	  const schema = await json(receiptSchemaPath);
481	  if (action === "cell") {
482	    await runCell(options.lane, options.task, options.host, Number(options.seed ?? 1), protocol, schema);
483	    return;
484	  }
485	  if (action !== "matrix") throw new Error("Usage: framework-harness.mjs cell --lane L0 --task product --host codex --seed 1 | matrix --concurrency 2");
486	  const cells = [];
487	  const seed = Number(options.seed ?? 1);
488	  const lanes = options.lanes ? options.lanes.split(",") : Object.keys(protocol.lanes);
489	  const tasks = options.tasks ? options.tasks.split(",") : Object.keys(protocol.tasks);
490	  const hosts = options.hosts ? options.hosts.split(",") : Object.keys(protocol.hosts);
491	  for (const lane of lanes) for (const task of tasks) for (const host of hosts) cells.push({ lane, task, host, seed });
492	  const concurrency = Number(options.concurrency ?? 2);
493	  let cursor = 0;
494	  const workers = Array.from({ length: concurrency }, async () => {
495	    while (cursor < cells.length) {
496	      const cell = cells[cursor];
497	      cursor += 1;
498	      await runCell(cell.lane, cell.task, cell.host, cell.seed, protocol, schema);
499	    }
500	  });
501	  await Promise.all(workers);
502	}
